const item = $input.first().json;
const headers = item.headers ?? {};
const provided = String(headers['x-n8n-secret'] ?? headers['X-N8N-Secret'] ?? '');
const expected = String($env.N8N_WEBHOOK_SECRET ?? '');
if (!expected) throw new Error('N8N_WEBHOOK_SECRET is not configured in n8n');
if (provided.length !== expected.length) throw new Error('Unauthorized: bad webhook secret');
let diff = 0;
for (let i = 0; i < expected.length; i++) diff |= provided.charCodeAt(i) ^ expected.charCodeAt(i);
if (diff !== 0) throw new Error('Unauthorized: bad webhook secret');
return [$input.first()];

// Pluggable product sources (§3). Each source is a stub returning
// candidate products. Replace stubs with real permitted feeds/APIs
// (affiliate network APIs, public product feeds). Respect robots/ToS.
const SOURCES = [
  { name: 'stub-source', note: 'STUB — plug a real permitted product feed/API here' },
];
const STUB_CANDIDATES = []; // intentionally empty: no fake products invented
const body = ($input.first().json.body ?? $input.first().json);
return [{ json: { date: body.date ?? null, sources: SOURCES.map(s => s.name),
  candidates: STUB_CANDIDATES } }];

const j = $input.first().json;
// Compliance pre-filter (§5, Deobandi fiqh): never promote disallowed products.
const DENY = [/alcohol/i, /pork/i, /gambling|betting|casino|lottery/i,
  /tobacco|cigarette|vape/i, /weapon|firearm/i, /adult|porn/i,
  /interest\s*free\s*loan|riba/i];
const seen = new Set();
const products = [], rejected = [];
for (const c of (j.candidates ?? [])) {
  const key = String(c.url ?? c.title ?? '').toLowerCase().trim();
  if (!key || seen.has(key)) { rejected.push({ c, reason: 'duplicate' }); continue; }
  seen.add(key);
  const hay = (c.title ?? '') + ' ' + (c.category ?? '') + ' ' + (c.description ?? '');
  if (DENY.some(rx => rx.test(hay))) { rejected.push({ c, reason: 'compliance_prefilter' }); continue; }
  products.push({ ...c, state: 'DISCOVERED', discoveredAt: new Date().toISOString() });
}
// NOTE: persistence to a products table is TODO — no /api/v1/products
// endpoint exists yet. State travels in the payload for now.
return [{ json: { products, rejected,
  note: 'persistence TODO (no products endpoint yet)' } }];

const j = $input.first().json;
console.log('[discovery] done', JSON.stringify({ found: (j.products ?? []).length, rejected: (j.rejected ?? []).length }));
return [{ json: { ok: True, found: (j.products ?? []).length } }];

// Unwrap the season-rank response; fall back to the dedup order when the
// ranking call failed (ranking is a nudge, never a gate).
const r = $input.first().json;
const ranked = (r.data ?? r).products;
const prev = $('dedup-filter').first().json;
const products = Array.isArray(ranked) && ranked.length ? ranked : (prev.products ?? []);
return [{ json: { ...prev, products } }];
